// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzz: depositAmount is fuzzed; attackerAddr is not needed because we deploy an attacker contract
    function testFuzz_property(uint256 depositAmount) public {
        // keep deposit in a reasonable range (non-zero, not overflowing contract balance assumptions)
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy an attacker helper that will reenter withdrawAll when it receives funds
        attacker = new Attacker(address(c));

        // fund attacker so it can call deposit
        vm.deal(address(attacker), depositAmount);

        // attacker deposits into C under its own address
        attacker.deposit{value: depositAmount}();

        // Now call withdrawAll from attacker which will try to reenter during the external call
        // Wrap in try/catch to observe success/failure but the property we assert is about stored credit being zero
        bool ok;
        try attacker.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the reference: after withdrawAll completes, the caller's credit (getter) is zero.
        // We observe this via c.balance-like/public surface: credit is private in original source, but there is no getter.
        // However the described contract had mapping credit (not public). We cannot read private mapping.
        // Instead, we can observe address(c).balance: after a successful withdrawAll by the depositor, the contract's balance must have decreased by at least depositAmount (i.e., not increased) for the reference; the mutant can be reentered to drain more than intended causing different final contract balance.
        // We assert that address(c).balance <= address(this).balance + 1 ether + 1 wei + address(attacker).balance; // Not reliable.
        // Instead, we assert the property: after withdraw, the attacker cannot withdraw more than it deposited from the contract in total, so contract balance is not decreased below zero. To make a single universal assert that fails on the mutant, we check that the contract's balance is strictly less than or equal to initial contract balance minus depositAmount (i.e., deposit was paid out), which holds for reference and is broken if reentrancy drains more.

        // Record initial contract balance before withdraw: it's zero + depositAmount from attacker deposit
        // But setUp had c freshly deployed with zero balance; after deposit, contract balance should be depositAmount
        // For reference: after withdraw completes, contract balance == 0. For mutant exploited by reentrancy, contract.balance could be <0 (impossible) or still 0 but attacker may have drained others; to craft a distinguishing single assertion we assert that address(c).balance == 0 after withdraw completes.

        // Single required assertion reading c: reference satisfies that after a depositor withdraws, contract balance is zero (since only that depositor funded it), but the mutant when reentered could allow draining more or leave inconsistent state for some inputs; the fuzzer will find depositAmount that triggers reentrancy behavior making this assertion fail on mutant.
        assertTrue(address(c).balance == 0);
    }
}

// Minimal attacker that re-enters withdrawAll during receive()
contract Attacker {
    address public target;
    bool public first = true;

    constructor(address _target) payable {
        target = _target;
    }

    // deposit into target
    function deposit() external payable {
        // call C.deposit() with this contract as sender
        (bool ok, ) = target.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(ok);
    }

    // initiate withdraw which calls into target.withdrawAll()
    function withdraw() external {
        (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
        require(ok);
    }

    // When receiving funds, attempt to re-enter withdrawAll once to exploit mutant ordering
    receive() external payable {
        if (first) {
            first = false;
            // re-enter
            (bool ok, ) = target.call(abi.encodeWithSignature("withdrawAll()"));
            // ignore success/failure here
            ok;
        }
    }
}

