pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to deposit (must be >0) and an arbitrary attacker seed to vary behavior
    function testFuzz_property(uint256 depositAmount, uint256 attackerSeed) public {
        vm.assume(depositAmount > 0 && depositAmount <= 1 ether);

        // deploy attacker which will reenter during receive to try to exploit mutant ordering
        Attacker att = new Attacker(c);

        // fund attacker externally so it can deposit
        address attackerAddr = address(att);
        vm.deal(attackerAddr, depositAmount + 1 wei);

        // deposit from attacker into C
        vm.prank(attackerAddr);
        c.deposit{value: depositAmount}();

        // Ensure deposit recorded (we observe via public getter credit)
        uint256 beforeCredit = address(c).balance; // not used in assertion, just readable

        // Now trigger withdrawAll which will call attacker; in reference contract this clears credit after external call
        // For detection we will check the recorded credit after withdrawAll completes
        vm.prank(attackerAddr);
        // attacker will attempt reentrancy during the external call to withdrawAll
        c.withdrawAll();

        // Single assertion: after withdrawAll completes, the recorded credit for attacker must be zero in the correct contract
        // This reads the public mapping getter for credit deployed in C (mapping name: credit)
        // If the mutant that clears credit before external call is present and reentrancy succeeded, this may be nonzero
        assertTrue(c.credit(attackerAddr) == 0);
    }
}

// Minimal reentrant attacker: on receiving funds it attempts to reenter withdrawAll once
contract Attacker {
    C public target;
    bool public reentered;
    constructor(C _t) { target = _t; }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // reenter withdrawAll during the external call
            target.withdrawAll();
        }
    }
}

