pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed: depositAmount and attackerInitialFunding
    function testFuzz_property(uint256 depositAmount, uint256 attackerInitialFunding) public {
        // keep amounts in sensible wide ranges but nonzero where useful
        depositAmount = bound(depositAmount, 1, 1 ether);
        attackerInitialFunding = bound(attackerInitialFunding, 0, 1 ether);

        // Deploy a reentrant attacker which will reenter withdrawAll during receive
        ReentrantAttacker attacker = new ReentrantAttacker(address(c));

        // Fund attacker so it can deposit and pay for reentrancy gas
        if (attackerInitialFunding > 0) {
            vm.deal(address(attacker), attackerInitialFunding);
        }

        // Honest depositor deposits some funds
        address depositor = address(0xABCD);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();

        // Attacker deposits a small amount so it has credit that can be withdrawn
        uint256 attackerDeposit = 1; // small nonzero to enable withdraw path
        vm.deal(address(attacker), attackerDeposit + attackerInitialFunding);
        attacker.fundAndDeposit{value: attackerDeposit}();

        // Now attacker will call withdrawAll which in the mutant can be reentered
        // and may cause balance bookkeeping mismatch. We call through attacker
        // so its receive() triggers reentrancy attempts.
        attacker.launchWithdraw();

        // The universal property to check: contract balance must equal internal balance
        // (reference implementation always maintains consistency; mutant may not)
        assertTrue(address(c).balance == c.balance());
    }
}

// Minimal reentrant attacker: on receiving funds it tries to reenter withdrawAll once
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(address _target) payable {
        target = C(_target);
        reentered = false;
    }

    // Fund this contract and deposit into target
    function fundAndDeposit() external payable {
        // deposit into target to get credit
        target.deposit{value: msg.value}();
    }

    // Start withdraw process
    function launchWithdraw() external {
        // call withdrawAll on target to trigger external call to this contract
        target.withdrawAll();
    }

    // receive will attempt a single reentrant call into withdrawAll
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to reenter withdrawAll; in reference this should be blocked by lock
            // in mutant this may succeed and disturb bookkeeping
            target.withdrawAll();
        }
    }
}

